const results = [];
for (const section of $json.sections) {
  results.push({
    json: {
      company: $json.company,
      section: section
    }
  });
}
return results;

// Extract LLM response and parse it
const company = $json.company;
const section = $json.section;
const llmResponse = $json.choices?.[0]?.message?.content || '{}';

let parsedResponse;
try {
  // Try to parse the JSON response from LLM
  parsedResponse = JSON.parse(llmResponse);
} catch (e) {
  // If parsing fails, create a default response
  parsedResponse = {
    status: 'requires_human',
    findings: llmResponse,
    missing_data: ['LLM response parsing failed'],
    human_tasks: ['Manual review required'],
    confidence_score: 0
  };
}

return {
  json: {
    company: company,
    section: section,
    status: parsedResponse.status || 'requires_human',
    findings: parsedResponse.findings || '',
    missing_data: parsedResponse.missing_data || [],
    human_tasks: parsedResponse.human_tasks || [],
    confidence_score: parsedResponse.confidence_score || 0
  }
};
